CREATE TABLE IF NOT EXISTS gn_divisions (
  id UUID PRIMARY KEY,
  ds_division_id UUID NOT NULL REFERENCES ds_divisions(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  gn_code TEXT NULL,
  mpa_code TEXT NULL,
  name_si TEXT NULL,
  name_ta TEXT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(ds_division_id, name)
);

